const APPLE_TOUCH_ICON_180 = "";
const APP_ICON_192 = "";
const APP_ICON_512 = "";

const ICON_VERSION = "pacifico-2";

function decodeBase64(value: string): ArrayBuffer {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes.buffer;
}

function pngResponse(value: string): Response {
  return new Response(decodeBase64(value), {
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=86400"
    }
  });
}

export function handleAppleTouchIcon(): Response {
  return pngResponse(APPLE_TOUCH_ICON_180);
}

export function handleAppIcon(size: 192 | 512): Response {
  return pngResponse(size === 512 ? APP_ICON_512 : APP_ICON_192);
}

export function handleWebManifest(): Response {
  return new Response(JSON.stringify({
    name: "Aelios Memory",
    short_name: "Aelios",
    description: "Aelios memory console",
    start_url: "/admin",
    scope: "/",
    display: "standalone",
    background_color: "#f7f5fb",
    theme_color: "#f7f5fb",
    icons: [
      {
        src: `/icons/aelios-192.png?v=${ICON_VERSION}`,
        sizes: "192x192",
        type: "image/png",
        purpose: "any maskable"
      },
      {
        src: `/icons/aelios-512.png?v=${ICON_VERSION}`,
        sizes: "512x512",
        type: "image/png",
        purpose: "any maskable"
      }
    ]
  }), {
    headers: {
      "content-type": "application/manifest+json; charset=utf-8",
      "cache-control": "public, max-age=300"
    }
  });
}
